-    expect(ZimmDrawer.parts).toEqual(['overlay', 'content', 'closeButton', 'header', 'headerTitle']);
+describe('ZimmDrawer — parts array', () => {
+  // SFCC-831/689 rework: gains exactly one new part, `headerCloseButton` (the boxed close
+  // button's own 44px row — see zimmDrawer.css.ts), fixing the tester-caught defect where
+  // `prompt.header`'s paddingBlock-driven height had no real row height to measure against.
+  test('gains headerCloseButton, the one new part introduced by this rework', () => {
+    expect(ZimmDrawer.parts).toEqual([
+      'overlay',
+      'content',
+      'closeButton',
+      'header',
+      'headerTitle',
+      'headerCloseButton',
+    ]);
+  });
+});
+
+// Completeness gap flagged by the Scorer: the parts-array test above only proves the part's
+// NAME exists, not its style values, and `prompt.header`'s own new md+ values had no coverage
+// at all — unlike `prompt.content`'s bottom/height/maxHeight above, which already had exactly
+// this kind of value assertion. Both assertions below were proven red against the pre-rework
+// shape first (headerCloseButton commented out of baseStyle; prompt.header's key removed
+// entirely), then reverted, per this file's own established method.
+describe('ZimmDrawer — headerCloseButton (SFCC-831/689 rework)', () => {
+  test('gives the boxed close button a real 44px in-flow row', () => {
+    expect(ZimmDrawer.baseStyle.headerCloseButton.height).toBe('2.75rem'); // DRAWER_HEADER_ROW_HEIGHT
+  });
+
+  test("prompt's header switches to auto-height/24px padding above md", () => {
+    const aboveMd = stylesAboveMd(ZimmDrawer.variants.prompt.header);
+    expect(aboveMd.minHeight).toBe('unset');
+    expect(aboveMd.paddingBlock).toBe('var(--zimm-scale-xl)'); // HEADER_PADDING_Y
   });
 });
